contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }

	// Drive the contract as the owner to change the bet limit, then observe it.
	function runTest(uint256 newLimit) public {
		// caller must be the owner of c for AdjustBetAmounts to succeed. We require that here.
		require(msg.sender == c.owner());
		// perform the state-changing call that should update the bet limit in the original contract
		c.AdjustBetAmounts(newLimit);
		// Assert that the publicly observable currentBetLimit() equals the newLimit provided.
		assert(c.currentBetLimit() == newLimit);
	}

	// expose owner getter through a small wrapper call to satisfy the requirement to only use c's public surface
	// Note: This wrapper is necessary because owner in C is private; we instead rely on the contract's behavior
