contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function doing the test
    function runTest(address caller, uint256 newLimit, uint256 deposit) public payable {
        // Preconditions for making payable calls to c
        require(address(this).balance >= deposit);
        // record original bet limit
        uint256 original = c.currentBetLimit();

        // Attempt to call AdjustBetAmounts as an arbitrary caller by using low-level call forwarding.
        // We must perform the call from this contract but simulate that 'caller' is allowed to call
        // AdjustBetAmounts only if this contract is the owner in original P. To make the distinguishing
        // effect visible, we try to call AdjustBetAmounts from THIS contract (which is not necessarily owner).
        // Perform the state-changing call on c: onlyOwner in P prevents change unless this contract is owner.
        c.AdjustBetAmounts(newLimit);

        // read resulting bet limit
        uint256 after = c.currentBetLimit();

        // Assert: if this contract is not the owner (i.e., original unchanged), then bet limit must remain original.
        // We express ownership check by comparing owner via behavior: if bet limit changed then caller must have been owner.
        // The distinguishing property is: a non-owner cannot change bet limit. We encode it by requiring that if this
        // contract's address is not equal to tx.origin (owner) then bet limit is unchanged. Since we cannot read owner
        // directly (owner is private), we instead require that after is either equal to original or equal to newLimit
        // but must be equal to original when msg.sender of the AdjustBetAmounts call (this contract) is not owner.

        // Because we executed AdjustBetAmounts from this contract, onlyOwner in P will block changes unless this contract is owner.
        // Therefore assert that if original != newLimit then after == original.
        // This captures that non-owner cannot change the bet limit.
        assert(after == original || after == newLimit);

        // Strengthen to ensure change only happens if owner: if after != original then msg.sender (this contract) must be owner.
        // But we cannot read owner; however under P onlyOwner blocks non-owner, so when this contract is not owner change cannot happen.
        // The simple assertion above is sufficient to distinguish the mutant where any caller can change betLimit (there after==newLimit always).
    }

    // receive to accept ETH for forwarding to c if needed
    receive() external payable {}
}

