    C c;
    constructor(C _c) { c = _c; }
    // caller of run(...) must be a non-owner and a real EOA (msg.sender == tx.origin)
    function run(uint256 newLimit) public payable {
        require(tx.origin == msg.sender); // ensure real EOA
        // establish the state the difference needs: call play() which requires the player to have wagered and be openToPublic,
        // but we don't have to satisfy those here; we only need play() to be callable in the sequence specified.
        // However play() will revert unless preconditions hold; to keep the test general we call play() and ignore its revert.
        // We must call it as a top-level statement. If it reverts, the whole tx would revert — so instead we call a no-op
        // that is valid: use try/catch to call play() and continue regardless of revert, but the contract requires top-level state-changing calls
        // to be standalone. So we perform a try/catch at top level.
        bool playedReverted;
        try c.play() {
            playedReverted = false;
        } catch {
            playedReverted = true;
        }
        // Now attempt to adjust bet amounts and record whether it reverts.
        bool adjustedReverted;
        try c.AdjustBetAmounts(newLimit) {
            adjustedReverted = false;
        } catch {
            adjustedReverted = true;
        }
        // Rule: If the caller is NOT the contract owner, AdjustBetAmounts must revert. We cannot read owner, so express caller-not-owner
        // via the fact that AdjustBetAmounts should revert for any caller except the true owner. Here we require that the caller is not owner
        // by observing that a successful AdjustBetAmounts would imply caller is owner; we assert the converse: if caller is not owner then it reverts.
        // We encode as: adjustedReverted == true (i.e., must revert) because this test is run by a non-owner account. To ensure non-owner, assert that
        // the call to AdjustBetAmounts did not succeed; but we must make the assert a general rule over parameters and revert flags.
        // Use the parameter newLimit and the revert flag: assert(adjustedReverted || newLimit == newLimit) is trivial; instead assert(adjustedReverted);
        // That states the rule that non-owner callers cannot adjust the bet amount. This will hold on original P and fail on M.
        assert(adjustedReverted);
    }
    receive() external payable {}
}

